tokens:
--scheme: dark;
color-scheme: dark;
--bg: #0e1117;
--bg2: #121620;
--surface: #181d27;
--surface2: #212836;
--ink: #f3f5f9;
--muted: #cdd3df;
--faint: #a6aebd;
--cardmeta: #dfe3ec;
--gold: #ffcc4d;
--gold-soft: #ffe08f;
--gold-deep: #8a6a14;
--on-gold: #14110a;
--ink-soft: #cdd3df;
--line: rgba(243, 245, 249, 0.12);
--line-strong: rgba(255, 204, 77, 0.45);
--ok: #7fe39a;
--warn: #ffcf5c;
--bad: #ff8f7a;
--shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 18px 50px rgba(0, 0, 0, 0.65);
--elev-1: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 2px 8px rgba(0, 0, 0, 0.45);
--elev-2: inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 12px 30px rgba(0, 0, 0, 0.55);
--elev-3: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 28px 80px rgba(0, 0, 0, 0.75);
--scrim: rgba(0, 0, 0, 0.62);
--focus: #ffe08f;
--th-bg: #212836;
--tabgrad1: #212836; --tabgrad2: #181d27;
--toastgrad1: #212836; --toastgrad2: #181d27;
--foot-bg: rgba(14, 17, 23, 0.94);
--drawerbar-bg: rgba(24, 29, 39, 0.96);
--ph-bg: #212836;
--sel-bg: rgba(255, 204, 77, 0.18);
--row-hover: rgba(255, 204, 77, 0.07);
--hold-bg: linear-gradient(135deg, #212836, #181d27);
--skeleton1: #212836; --skeleton2: #0e1117;
--grain-op: 0.04;
--wing-dur: 0.45s;
--wing-rise: 18px;
/* legacy aliases resolved on <html> */
--text: var(--ink); --panel: var(--surface); --chip: var(--surface2); --missing: var(--faint);
--border: var(--line); --gold-dim: var(--gold-deep); --danger: var(--bad);
--serif: "Helvetica Neue", Helvetica, Arial, system-ui, sans-serif;
--mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
--radius: 12px;
/* the spring treatment (styles/style-layer.css, ui "spring"): an overshooting ease and the lab grid's line colour */
--spring: cubic-bezier(0.34, 1.9, 0.5, 1);
--lab-grid: rgba(160, 180, 220, 0.07);

